       const atividadeId = gerarIdAtividade();
       const agora = new Date().toISOString();

       // Inserir atividade
       db.run(
         `INSERT INTO atividades (id, titulo, tipo, sala_id, vagas, situacao, criada_em) VALUES (?, ?, ?, ?, ?, 'prevista', ?)`,
         [atividadeId, titulo, tipo, salaId, vagas, agora]
