    await new Promise<void>((resolve) => server.listen({ port: 3011 }, resolve));
  });

  after(async () => {
    await server.close();
    delete process.env.MODO_TESTE;
    delete process.env.PORT;
  });

  // ============================================================
  // CRIAÇÃO (POST /atividades)
