        titulo: "Precedencia R1+R3",
        tipo: "palestra",
        salaId: "sala_01",
        vagas: 10,
        encontros: [
          { inicio: "2026-10-19T10:00:00-03:00", fim: "2026-10-19T10:30:00-03:00" },
          { inicio: "2026-10-20T10:00:00-03:00", fim: "2026-10-20T11:00:00-03:00" },
        ],
      }),
    });
    assert.equal(status, 422);
