    assert.ok(encId.startsWith("enc_"));
    assert.equal(encId.length, 12);
    assert.ok(/^enc_[0-9a-f]{8}$/.test(encId));
  });

  it("ID malformado em GET /atividades/:id → 400 ID_INVALIDO", async () => {
    await fetchJson("/_teste/reset", { method: "POST" });
