it("Sem limite global: criar atividades sem conflito → 201", async () => {
    await fetchJson("/_teste/reset", { method: "POST" });
    const salas = ["sala_01", "sala_02", "sala_03"];
    // Cria 30 atividades (10 por sala) distribuídas nas 3 salas, dias diferentes e horários
    let count = 0;
    for (const salaId of salas) {
      for (let dia = 19; dia <= 23; dia++) {
        for (let hora = 8; hora <= 16; hora += 4) {
          if (count >= 30) break;
          const { status } = await fetchJson("/atividades", {
            method: "POST",
            headers: { "X-Usuario": "org-ana" },
            body: JSON.stringify({
              titulo: `Atividade ${count}`,
              tipo: "palestra",
              salaId,
              vagas: 10,
              encontros: [{ inicio: `2026-10-${dia.toString().padStart(2, '0')}T${hora.toString().padStart(2, '0')}:00:00-03:00`, fim: `2026-10-${dia.toString().padStart(2, '0')}T${(hora+2).toString().padStart(2, '0')}:00:00-03:00` }]
            }),
          });
          assert.equal(status, 201);
          count++;
        }
        if (count >= 30) break;
      }
      if (count >= 30) break;
    }
    assert.ok(count >= 30);
  });

