input.content:
import { createServer } from "./src/server.js";

async function test() {
  process.env.MODO_TESTE = "1";
  process.env.PORT = "3014";
  const app = await createServer();
  await app.listen({ port: 3014 });

  await fetch("http://localhost:3014/_teste/reset", { method: "POST" });

  // 1. JSON inválido → 422 DADOS_INVALIDOS
  const r1 = await fetch("http://localhost:3014/atividades", { method: "POST", headers: { "Content-Type": "application/json", "X-Usuario": "org-ana" }, body: "invalid json" });
  const b1 = await r1.json();
  console.log("1. JSON inválido:", r1.status, "-", b1.erro);

  // 2. Cancelamento usa situacao
  const c = await fetch("http://localhost:3014/atividades", { method: "POST", headers: { "Content-Type": "application/json", "X-Usuario": "org-ana" }, body: JSON.stringify({ titulo: "Teste", tipo: "palestra", salaId: "sala_01", vagas: 10, encontros: [{ inicio: "2026-10-19T10:00:00-03:00", fim: "2026-10-19T12:00:00-03:00" }] }) });
  const atv = await c.json();

  // Avancar relogio para durante
  await fetch("http://localhost:3014/_teste/relogio", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ agora: "2026-10-19T11:00:00-03:00" }) });

  const r2 = await fetch("http://localhost:3014/atividades/" + atv.id + "/cancelamento", { method: "POST", headers: { "X-Usuario": "org-ana" } });
  const b2 = await r2.json();
  console.log("2. Cancelar em_andamento:", r2.status, "-", b2.erro);

  // 3. Título só espaços
  const r3 = await fetch("http://localhost:3014/atividades", { method: "POST", headers: { "Content-Type": "application/json", "X-Usuario": "org-ana" }, body: JSON.stringify({ titulo: "   ", tipo: "palestra", salaId: "sala_01", vagas: 10, encontros: [{ inicio: "2026-10-19T10:00:00-03:00", fim: "2026-10-19T12:00:00-03:00" }] }) });
  const b3 = await r3.json();
  console.log("3. Título espaços:", r3.status, "-", b3.titulo);

  await app.close();
}
test().catch(console.error);

